    function automata.make_dfa_conf(dfa, state, word, purpose)
        assert(type(state) == "string" or type(state) == "nil")
        --        assert(type(word) == "string")
        assert(type(purpose) == "string")
        if type(word) == "string" then
            local map = {}
            for k, _ in pairs(dfa:get_symbols()) do
                map[k] = k
            end
            word = automata.tokenise_word(word, map)
        end

        local conf = { automaton = dfa, state = state, word = word, purpose=purpose }

        setmetatable(conf, finite_automata_conf_metatable)

        function conf:get_automaton()
            return self.automaton
        end

        function conf:get_state()
            return self.state
        end

        function conf:get_word()
            return self.word
        end

        function conf:is_finished()
            if self.purpose == "acceptance" then
                return self:get_word():len() == 0 or not self:get_state()
            elseif self.purpose == "generation" then
                return true
            else
                error(self.purpose)
            end
        end

        if purpose == "acceptance" then
            function conf:step()
                local dfa = self:get_automaton()
                assert(type(self) == "table")
                local state = self:get_state()
                local word = self:get_word()
                local new_word, input = word:pop_left_copy()
                local next_state = dfa:get_to_states(state, input)
                local result = {}
                if next_state then
                    table.insert(result, automata.make_dfa_conf(dfa, next_state, new_word, self.purpose))
                end
                return result
            end
        elseif purpose == "generation" then
            function conf:step()
                local dfa = self:get_automaton()
                local state = self:get_state()
                if not state then
                    return {}
                end
                local word = self:get_word()
                local result = {}
                for input, _ in pairs(dfa:get_symbols()) do
                    local new_word = word:insert_right_copy(input)
                    local next_state = dfa:get_to_states(state, input)
                    if next_state then
                        table.insert(result, automata.make_dfa_conf(dfa, next_state, new_word, self.purpose))
                    end
                end
                return result
            end
        end

        function conf:is_accepting()
            return self:is_finished() and toboolean(self:get_state()) and self:get_automaton():is_accepting(self:get_state())
        end

        return conf
    end

