                        table.insert(result, automata.make_nfa_conf(nfa, next_state, new_word, self.purpose))
                    end
                end
                if nfa:get_type() == "nfa-lambda" then
                    local next_states = nfa:get_to_states(state, "")
                    for next_state, _ in pairs(next_states) do
